From 06bc3d183d19fbbe516bb3b3e8544247674501b6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:04:27 +0100
Subject: [PATCH] osd: add an option to turn off all screens

The Meta+P selector had no way to turn every screen off while leaving
the computer running. Add a "Turn off screens" option that uses DPMS
like the Turn Off Screen shortcut, so any input turns them back on.

BUG: 524906
---
 common/osdaction.cpp       | 2 ++
 common/osdaction.h         | 1 +
 osd/CMakeLists.txt         | 1 +
 osd/osdmanager.cpp         | 9 +++++++++
 osd/osdmanager.h           | 2 ++
 plasmoid/kscreenapplet.cpp | 4 ++--
 6 files changed, 17 insertions(+), 2 deletions(-)

diff --git a/common/osdaction.cpp b/common/osdaction.cpp
index 0f41f2f9..fd7d50fa 100644
--- a/common/osdaction.cpp
+++ b/common/osdaction.cpp
@@ -29,6 +29,7 @@ QList<OsdAction> OsdAction::availableActions()
         {Clone, i18nd("kscreen_common", "Mirror screens"), QStringLiteral("osd-duplicate")},
         {ExtendLeft, i18nd("kscreen_common", "Extend to left of built-in screen"), QStringLiteral("osd-sbs-left")},
         {ExtendRight, i18nd("kscreen_common", "Extend to right of built-in screen"), QStringLiteral("osd-sbs-sright")},
+        {TurnOffScreens, i18nd("kscreen_common", "Turn off screens"), QStringLiteral("system-shutdown")},
         {NoAction, i18nd("kscreen_common", "Leave unchanged"), QStringLiteral("dialog-cancel")},
     };
 }
@@ -57,6 +58,7 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen

     switch (action) {
     case KScreen::OsdAction::Action::NoAction:
+    case KScreen::OsdAction::Action::TurnOffScreens:
         return nullptr;
     case KScreen::OsdAction::Action::SwitchToExternal:
         internal->setEnabled(false);
diff --git a/common/osdaction.h b/common/osdaction.h
index 1668fb48..8553961b 100644
--- a/common/osdaction.h
+++ b/common/osdaction.h
@@ -35,6 +35,7 @@ public:
         Clone,
         ExtendLeft,
         ExtendRight,
+        TurnOffScreens,
     };
     Q_ENUM(Action)

diff --git a/osd/CMakeLists.txt b/osd/CMakeLists.txt
index cb6b692d..ed03322a 100644
--- a/osd/CMakeLists.txt
+++ b/osd/CMakeLists.txt
@@ -12,6 +12,7 @@ target_link_libraries(kscreen_osd_service PRIVATE
     KF6::I18n
     KF6::WindowSystem
     KF6::Screen
+    KF6::ScreenDpms
     Plasma::Plasma
     LayerShellQt::Interface
 )
diff --git a/osd/osdmanager.cpp b/osd/osdmanager.cpp
index 94de4f7a..11bae389 100644
--- a/osd/osdmanager.cpp
+++ b/osd/osdmanager.cpp
@@ -14,6 +14,7 @@
 #include <KScreen/GetConfigOperation>
 #include <KScreen/Output>
 #include <KScreen/SetConfigOperation>
+#include <KScreenDpms/Dpms>

 #include <QDBusConnection>
 #include <QDBusMessage>
@@ -25,6 +26,7 @@ namespace KScreen
 OsdManager::OsdManager(QObject *parent)
     : QObject(parent)
     , m_cleanupTimer(new QTimer(this))
+    , m_dpms(new KScreen::Dpms(this))
 {
     new OsdServiceAdaptor(this);

@@ -102,6 +104,13 @@ void OsdManager::showActionSelector()
             osd = new KScreen::Osd(osdOutput, this);
             m_osds.insert(osdOutput->name(), osd);
             connect(osd, &Osd::osdActionSelected, this, [this, cfg = op->config()](OsdAction::Action action) {
+                if (action == OsdAction::TurnOffScreens) {
+                    if (m_dpms->isSupported()) {
+                        m_dpms->switchMode(KScreen::Dpms::Off);
+                    }
+                    hideOsd();
+                    return;
+                }
                 auto job = OsdAction::applyAction(cfg, action);
                 if (!job) {
                     hideOsd();
diff --git a/osd/osdmanager.h b/osd/osdmanager.h
index 29c06e2b..b8e79e41 100644
--- a/osd/osdmanager.h
+++ b/osd/osdmanager.h
@@ -17,6 +17,7 @@
 namespace KScreen
 {
 class ConfigOperation;
+class Dpms;
 class Osd;
 class Output;

@@ -43,6 +44,7 @@ private:
     void quit();
     QMap<QString, KScreen::Osd *> m_osds;
     QTimer *m_cleanupTimer;
+    Dpms *m_dpms;
 };

 } // ns
diff --git a/plasmoid/kscreenapplet.cpp b/plasmoid/kscreenapplet.cpp
index b48b785d..9f733743 100644
--- a/plasmoid/kscreenapplet.cpp
+++ b/plasmoid/kscreenapplet.cpp
@@ -75,9 +75,9 @@ QVariant KScreenApplet::availableActions()
 {
     auto actions = KScreen::OsdAction::availableActions();
     QList<KScreen::OsdAction> ret;
-    ret.reserve(actions.size() - 1);
+    ret.reserve(actions.size() - 2);
     for (const auto &action : actions) {
-        if (action.action != KScreen::OsdAction::NoAction) {
+        if (action.action != KScreen::OsdAction::NoAction && action.action != KScreen::OsdAction::TurnOffScreens) {
             ret.append(action);
         }
     }
